bool RingBuffer::push(int value) {
    if (full()) return false;
    data_[(head_ + count_) % data_.size()] = value;
    ++count_;
    return true;
}

bool RingBuffer::pop(int& out) {
    if (count_ == 0) return false;
    out = data_[head_];
    head_ = (head_ + 1) % data_.size();
    --count_;
    return true;
}

std::size_t RingBuffer::size() const { return count_; }

bool RingBuffer::full() const { return count_ == data_.size(); }

#include "ring_buffer.h"
#include <cstdio>
int main() {
    RingBuffer rb(2);
    rb.push(1); rb.push(2);
    std::printf("third push accepted: %d, size: %zu\n", (int)rb.push(3), rb.size());
    int v = 0;
    rb.pop(v); rb.push(4);
    int a = 0, b = 0;
    rb.pop(a); rb.pop(b);
    return (v == 1 && a == 2 && b == 4 && rb.size() == 0) ? 0 : 1;
}

